"""Build the self-contained illustrated TH/EN/JA employee manual from reviewed application flows.

Run: python scripts/build-employee-operation-manual.py
The build is offline and read-only to application sources; captured UI screenshots are embedded.
"""
from pathlib import Path
from html import escape
import re

ROOT = Path(__file__).resolve().parents[1]
CHAPTERS = []


def table(headers, rows):
    return '<div class="table-scroll"><table><thead><tr>' + ''.join('<th scope="col">' + h + '</th>' for h in headers) + '</tr></thead><tbody>' + ''.join('<tr>' + ''.join('<td>' + c + '</td>' for c in row) + '</tr>' for row in rows) + '</tbody></table></div>'


def note(text):
    return '<aside class="note"><strong>ข้อควรรู้</strong><p>' + text + '</p></aside>'


def proc(title, steps, result, extra=''):
    return '<details class="procedure" open><summary>' + title + '</summary><div class="procedure-body"><ol>' + ''.join('<li>' + s + '</li>' for s in steps) + '</ol><p class="result"><strong>ตรวจผลสำเร็จ</strong> ' + result + '</p>' + (note(extra) if extra else '') + '</div></details>'


def chapter(id, title, menu, audience, body, sources, views=''):
    CHAPTERS.append(dict(id=id, title=title, menu=menu, audience=audience, body=body, sources=sources.split(), views=views.split()))


